-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.search_notes(query text, max_results integer DEFAULT 30)
 RETURNS TABLE(note_id text, note_slug text, note_title text, course_name text, anchor text, section text, snippet text, score real)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select * from public.search_notes_except(query, max_results, '{}');
$function$;

grant execute on function public.search_notes(query text, max_results integer) to service_role;
